INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(178028,'03014','Museu Etnològic de Dénia','Museo','wikidata_museos','El Museu etnològic de Dénia (Marina Alta, País Valencià) tracta sobre els moments d''auge i esplendor que va viure la ciutat en la segona meitat del segle xix a causa del comerç de la pansa. Aquest fet va provocar un gran desenvolupament urbanístic i va crear un ambient cultural i una societat burgesa consolidada…',38.8406069,0.1059817,'https://ca.wikipedia.org/wiki/Museu_Etnològic_de_Dénia');
