INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,enlace,wiki_url) VALUES(178031,'17117','Museu del Suro','Museo','wikidata_museos','El Museu del Suro de Palafrugell és una institució cultural nascuda el 1972 que té per missió adquirir, conservar, interpretar i posar en valor el patrimoni vertebrat a l''entorn del món del suro a Catalunya, en tant que configura un paisatge, una indústria, unes formes de vida i una identitat comunes. Forma part de…',41.9182837,3.1650581,'https://visitmuseum.gencat.cat/en/museu-del-suro-de-palafrugell','https://ca.wikipedia.org/wiki/Museu_del_Suro_de_Palafrugell');
