INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,enlace,wiki_url) VALUES(178064,'08003','Museu Eròtic de Barcelona','Museo','wikidata_museos','El Museo de la Erótica de Barcelona - MEB (en catalán: Museu de l''Eròtica), a veces llamado Museo Erótico de Barcelona,​ es un museo de arte erótico ubicado en La Rambla de Barcelona. Fue el primer museo de España de temática sexual.​ Contiene alrededor de 800 obras de arte.',41.382243,2.1725665,'http://www.erotica-museum.com/','https://es.wikipedia.org/wiki/Museo_de_la_Erótica_de_Barcelona');
