INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(178066,'30030','Museo de la Catedral','Museo','wikidata_museos','El museo de la Catedral de Murcia (Región de Murcia, España) es un museo que forma parte del edificio de la catedral. Fue creado por deseo del obispo Miguel de los Santos e inaugurado en 1956.',37.9842522,-1.12895,'https://es.wikipedia.org/wiki/Museo_de_la_Catedral_de_Murcia');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(178067,'45017','Casa de l''Ensenyança','Museo','wikidata_museos','La Casa de l''Ensenyança va ser construïda en Xàtiva el 1758 per disposició de l''arquebisbe Mayoral per educar xiquets pobres, igual com havia fet a la ciutat de València. És obra de Fra José Alberto Pina, frare carmelita que va exercir com a arquitecte municipal i que va treballar també en l''obra de la Seu.',38.9873948,-0.5224546,'https://ca.wikipedia.org/wiki/Casa_de_l''Ensenyança');
