INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,enlace,wiki_url) VALUES(178167,'48020','Bilboko Arte Eder museoa','Museo','wikidata_museos','El Museo de Bellas Artes de Bilbao (en euskera: Bilboko Arte Ederren Museoa) está situado en la ciudad de Bilbao, en el norte de España. Está caracterizado por su amplitud cronológica, ya que cubre desde el siglo XIII hasta nuestros días, y por la gran diversidad de manifestaciones artísticas que contiene.',43.2654825,-2.9380144,'https://www.museobilbao.com/','https://es.wikipedia.org/wiki/Museo_de_Bellas_Artes_de_Bilbao');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,enlace,wiki_url) VALUES(178168,'29002','Museo de Aeronáutica y Astronáutica - Museo del Aire','Museo','wikidata_museos','Museo de Aeronáutica y Astronáutica, también conocido como Museo del Aire, es un museo de aeronáutica y astronáutica del Ejército del Aire y del Espacio en Madrid, cerca del Aeropuerto de Madrid-Cuatro Vientos, España. Es un museo nacional y de titularidad estatal, dependiente del Ministerio de Defensa a través del…',40.3651533,-3.8031922,'http://www.ejercitodelaire.mde.es/EA/museodelaire/index.html','https://es.wikipedia.org/wiki/Museo_de_Aeronáutica_y_Astronáutica');
