INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,enlace,wiki_url) VALUES(178170,'15036','Museo da Construción Naval Exponav','Museo','wikidata_museos','A Exposición Nacional da Construción Naval, tamén coñecida como Exponav, é un museo marítimo de Ferrol, adicado á historia da construción naval. Foi inaugurado o 10 de marzo de 2008, e está situado na base naval da cidade departamental.',43.4824509,-8.2312156,'https://www.exponav.org/','https://gl.wikipedia.org/wiki/Exposición_Nacional_da_Construción_Naval');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,enlace,wiki_url) VALUES(178171,'08003','Museu d''Art Contemporani de Barcelona','Museo','wikidata_museos','El Museu d''Art Contemporani de Barcelona, conegut també per les seves sigles MACBA, és un museu dedicat a l''exposició de l''art i les pràctiques culturals contemporànies. Està situat al barri del Raval de la ciutat de Barcelona, molt a prop del Centre de Cultura Contemporània de Barcelona.',41.3830995,2.166748,'https://www.macba.cat/','https://ca.wikipedia.org/wiki/Museu_d''Art_Contemporani_de_Barcelona');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,enlace,wiki_url) VALUES(178172,'01001','Casa das Ciencias','Museo','wikidata_museos','A Casa das Ciencias é un dos Museos Científicos Coruñeses. Está situado no Parque de Santa Margarida.',43.3620947,-8.4124754,'https://www.coruna.gal/mc2/gl/casa-das-ciencias','https://gl.wikipedia.org/wiki/Casa_das_Ciencias');
