INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,enlace,wiki_url) VALUES(178176,'08003','Museu Nacional d''Art de Catalunya','Museo','wikidata_museos','El Museu Nacional d''Art de Catalunya, també conegut amb les sigles MNAC, és un museu d''art de la ciutat de Barcelona que agrupa totes les arts amb la missió de conservar i exhibir la col·lecció d''art català més important del món, des del romànic fins a l''actualitat. El 2019 va rebre 837.700 visitants.',41.3683887,2.153478,'https://www.museunacional.cat/','https://ca.wikipedia.org/wiki/Museu_Nacional_d''Art_de_Catalunya');
