INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(178181,'20027','Lili Jauregia','Museo','wikidata_museos','Lili jauregia Zestoa udalerrian (Urola Kosta, Gipuzkoa) dagoen jauregi eta dorretxea da, XV. mendean gotiko estiloan eraikia. Jauregiaren eraikina multzo handiago baten parte da, bi burdinola, Lilibea etxea, bi errota eta urtegitxo bat lagun dituela.',43.237916,-2.2605524,'https://eu.wikipedia.org/wiki/Lili_jauregia');
