INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(178315,'17079','Museu del Cinema','Museo','wikidata_museos','El Museu del Cinema - Col·lecció Tomàs Mallol és un museu dedicat al món del cinema i als antecedents de la imatge i l''espectacle visual. Forma part de la Xarxa de Museus Locals de Catalunya-Girona.',41.9835656,2.8223613,'https://ca.wikipedia.org/wiki/Museu_del_Cinema-Col·lecció_Tomàs_Mallol');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(178316,'18005','Museu d''Art','Museo','wikidata_museos','El Museu d''Art de Girona és un museu fundat el 1976 i situat a l''edifici del Palau Episcopal de Girona, al costat de la catedral. Al museu s''hi pot contemplar per ordre cronològic l''art gironí a través d''èpoques i estils successius: romànic, gòtic, renaixement, barroc, realisme, modernisme i noucentisme.',41.987024,2.8267948,'https://ca.wikipedia.org/wiki/Museu_d''Art_de_Girona');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,enlace,wiki_url) VALUES(178317,'17079','Museu d''Història dels Jueus','Museo','wikidata_museos','El Museu d''Història dels Jueus de Girona està ubicat al centre Bonastruc ça Porta, al bell mig del Call de Girona. L''edifici, l''antic Casal Ferrer, es troba en l''espai del call que havia ocupat la sinagoga i les dependències adjacents al segle xv.',41.9860018,2.8253696,'https://www.girona.cat/call/cat/museu.php','https://ca.wikipedia.org/wiki/Museu_d''Història_dels_Jueus_(Girona)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,enlace,wiki_url) VALUES(178318,'18005','Banys Àrabs','Museo','wikidata_museos','Els banys àrabs de Girona són uns banys àrabs del municipi de Girona declarats bé cultural d''interès nacional. Es troben en un edifici d''estil romànic tardà construït el 1194, imitant l''estructura dels banys musulmans nord-africans.',41.9880708,2.8256957,'https://www.banysarabs.cat/','https://ca.wikipedia.org/wiki/Banys_àrabs_de_Girona');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,enlace,wiki_url) VALUES(178319,'33024','Museu etnográficu Pueblu d''Asturies','Museo','wikidata_museos','El Muséu del Pueblu d''Asturies ye un recintu de 35.000 m² asitiáu en Xixón (Asturies) y dedicáu la cultura y arquiteutura tradicional asturianes. Enantes yera conocíu como Muséu Etnográficu del Pueblu d''Asturies.',43.5379419,-5.6343466,'https://www.gijon.es/es/directorio/museu-del-pueblu-dasturies','https://ast.wikipedia.org/wiki/Muséu_del_Pueblu_d''Asturies');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,enlace) VALUES(178320,'01005','Museo do Faro','Museo','wikidata_museos','Museo en Camariñas (A Coruña).',43.159903,-9.2109517,'https://www.farovilan.com');
