INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,enlace) VALUES(178322,'07040','Museu Històric Militar','Museo','wikidata_museos','Museo en Palma de Mallorca (Islas Baleares).',39.5463479,2.6232328,'http://www.museomilitarsancarlos.com');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,enlace,wiki_url) VALUES(178323,'08003','Fundació Joan Miró','Museo','wikidata_museos','La Fundació Joan Miró és una institució cultural de Barcelona que custodia algunes de les obres més representatives d''aquest pintor català. Va ser ideada a partir del treball conjunt entre l''artista i l''arquitecte Josep Lluís Sert.',41.3686501,2.1598485,'https://www.fmirobcn.org/','https://ca.wikipedia.org/wiki/Fundació_Joan_Miró');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,enlace,wiki_url) VALUES(178324,'17066','Teatre-Museu Dalí','Museo','wikidata_museos','El Teatre-Museu Dalí de Figueres, inaugurat el 1974, forma part del «triangle dalinià» empordanès junt amb el Castell de Púbol i la Casa-Museu Salvador Dalí de Portlligat, tots gestionats per la Fundació Gala-Salvador Dalí. És considerat com l''objecte surrealista més gros del món.',42.268022,2.9594264,'https://www.salvador-dali.org/ca/museus/teatre-museu-dali-de-figueres/','https://ca.wikipedia.org/wiki/Teatre-Museu_Dalí');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,enlace,wiki_url) VALUES(178325,'46250','Centre Museístic la Beneficiència','Museo','wikidata_museos','El Centre Cultural la Beneficència és un centre cultural situat a l''antiga casa de la Beneficència de la ciutat de València. El seu origen és un antic hospici del segle xix, i en la dècada de 1990 va ser restaurat i preparat com a centre cultural i sala d''exposicions, on s''hi troben diferents institucions de l''àrea…',39.4787957,-0.3829982,'http://www.labeneficencia.es/','https://ca.wikipedia.org/wiki/Centre_Cultural_la_Beneficència');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,enlace,wiki_url) VALUES(178326,'46131','Palau Ducal dels Borja','Museo','wikidata_museos','Museo en Gandía (Valencia).',38.965781,-0.1800555,'https://www.palauducal.com/?i=es&subsec=hom','https://en.wikipedia.org/wiki/Ducal_Palace_of_Gandia');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,enlace,wiki_url) VALUES(178327,'08194','Torre de les Aigües del Besòs','Museo','wikidata_museos','La Torre de les Aigües del Besòs o de MACOSA és una edificació situada a la plaça de Ramon Calsina, al districte de Sant Martí de Barcelona, catalogada com a bé cultural d''interès local. Va ser construïda el 1882 sota la direcció de l''arquitecte Pere Falqués i Urpí, i la seva funció era garantir l''abastiment de la…',41.405785,2.2122985,'https://www.torredelesaigues.cat/','https://ca.wikipedia.org/wiki/Torre_de_les_Aigües_del_Besòs');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(178328,'18005','Museu d''Arqueologia de Catalunya','Museo','wikidata_museos','El Museu d''Arqueologia de Catalunya a Barcelona (MAC Barcelona) és un museu ubicat a l''antic Palau d''Arts Gràfiques, dins del Parc de Montjuïc. És la capçalera del Museu d''Arqueologia de Catalunya, i recull tot un seguit d''objectes i documents arqueològics que abracen un arc cronològic que va des de la Prehistòria…',41.9885674,2.8264915,'https://ca.wikipedia.org/wiki/Museu_d''Arqueologia_de_Catalunya_(Barcelona)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,enlace,wiki_url) VALUES(178329,'08003','Museu d''Arqueologia de Catalunya','Museo','wikidata_museos','El Museu d''Arqueologia de Catalunya (MAC) és un museu nacional que té com a objectiu la conservació, investigació i divulgació dels vestigis arqueològics a Catalunya, que il·lustrin els diferents períodes històrics compresos entre la prehistòria i l''època medieval. Va sorgir arran de la llei de museus de 1990 i és…',41.3697709,2.1576593,'http://www.macbarcelona.cat/','https://ca.wikipedia.org/wiki/Museu_d''Arqueologia_de_Catalunya');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud) VALUES(178330,'49242','Casa del parque «El palomar»','Museo','wikidata_museos','Museo en Villafáfila (Zamora).',41.8550486,-5.5943634);
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(178331,'45017','Hospital Reial','Museo','wikidata_museos','El Hospital Municipal, sito en la plaza Calixto III, del municipio de Játiva, en la comarca de La Costera, está catalogado como Bien de interés cultural con anotación ministerial número R-I-51-0004504 y fecha de disposición 5 de junio de 1981.​',38.9876875,-0.5194536,'https://es.wikipedia.org/wiki/Hospital_Municipal_de_Játiva');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,enlace,wiki_url) VALUES(178332,'46250','Museu de Belles Arts de València','Museo','wikidata_museos','El Museo de Bellas Artes de Valencia (en valenciano, Museu de Belles Arts de València) es un museo de titularidad estatal, gestionado por la Generalidad Valenciana. Por la importancia de sus colecciones, es uno de los primeros museos de pintura de España, siendo un claro referente en cuanto a maestros valencianos…',39.4792844,-0.3708633,'http://museobellasartesvalencia.gva.es/','https://es.wikipedia.org/wiki/Museo_de_Bellas_Artes_de_Valencia');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(178333,'12040','Museu de Belles Arts de Castelló','Museo','wikidata_museos','El Museo de Bellas Artes de Castellón, situado en la ciudad de Castellón de la Plana (España), es un edificio obra de Mansilla + Tuñón Arquitectos que ha sido reconocido en numerosos premios de arquitectura a nivel nacional, tales como el Premio de Arquitectura FAD 2001, el Premio Obra Excelente del año 2001…',39.9823918,-0.0301979,'https://es.wikipedia.org/wiki/Museo_de_Bellas_Artes_de_Castellón');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,enlace,wiki_url) VALUES(178334,'46250','Casa Museu Benlluire','Museo','wikidata_museos','Mariano Benlliure Gil (Valencia, 8 de septiembre de 1862-Madrid, 9 de noviembre de 1947) fue un escultor español, considerado como el último gran maestro del realismo decimonónico.',39.4807682,-0.3789781,'http://valencia.es/ayuntamiento/infociudad_accesible.nsf/vDocumentosWebListadov/55BB0B184AACB248C125739B0043B748?OpenDocument&bdOrigen=ayuntamiento/laciudad.nsf&idapoyo=7A56E0AFD4368CBFC12571A900268CE5&nivel=5&lang=2','https://es.wikipedia.org/wiki/Mariano_Benlliure');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(178335,'04052','Casa del Cine','Museo','wikidata_museos','La Casa del Cine de Almería es un centro cultural de la ciudad de Almería dedicado al papel desempeñado por la ciudad y provincia de Almería en la industria cinematográfica internacional como plató natural de películas, series, anuncios publicitarios y vídeos musicales.',36.8516882,-2.4408945,'https://es.wikipedia.org/wiki/Casa_del_Cine');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,enlace,wiki_url) VALUES(178336,'08003','Museu Marítim','Museo','wikidata_museos','El Museu Marítim de Barcelona (MMB), situat a les Drassanes Reials, es dedica a la interpretació i difusió de la cultura marítima catalana, en especial a la Mediterrània. Rep més de 350.000 visitants anuals (2024) i vol oferir una mirada contemporània sobre les històries marítimes conegudes i també sobre les…',41.3753128,2.1758566,'https://www.mmb.cat/','https://ca.wikipedia.org/wiki/Museu_Marítim_de_Barcelona');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(178337,'46250','Museu de les Ciències «Príncep Felip»','Museo','wikidata_museos','El Museu de les Ciències, abans anomenat Museu de les Ciències Princep Felip, és un museu de continguts científics, tecnològics i mediambientals amb una vocació didàctica que es troba al complex de la Ciutat de les Arts i de les Ciències de la ciutat de València. El museu, localitzat a l''interior de l''edifici…',39.4556333,-0.3518224,'https://ca.wikipedia.org/wiki/Museu_de_les_Ciències_Príncep_Felip');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,enlace) VALUES(178338,'46250','Museu del Corpus i Casa de les Roques','Museo','wikidata_museos','Museo en Valencia (Valencia).',39.4791113,-0.376805,'http://www.valencia.es/ayuntamiento/Infociudad_accesible.nsf/vDocumentosWebListado/3A693428E5AAA5B0C12572C20023FE0F?OpenDocument&bdOrigen=ayuntamiento/laciudad.nsf');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,enlace,wiki_url) VALUES(178339,'43037','Ciutadella Ibèrica de Calafell','Museo','wikidata_museos','La ciutadella ibèrica de Calafell és el nom amb què es coneix el jaciment arqueològic d''Alorda Park o ciutadella de les Toixoneres, situat a Calafell, (Baix Penedès), declarat bé cultural d''interès local. Fou habitat per la tribu ibera dels cossetans i probablement fou destruïda amb l''arribada dels romans.',41.1905643,1.5811385,'https://visit.calafell.cat/list/ciutadella-iberica/','https://ca.wikipedia.org/wiki/Ciutadella_ibèrica_de_Calafell');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,enlace) VALUES(178340,'36004','Museo do Viño','Museo','wikidata_museos','Museo en Cambados (Pontevedra).',42.5116876,-8.8086162,'https://www.museosdelvino.es/museos/museo-etnografico-e-do-vino-de-cambados/');

